import{_ as a,o,c as d,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const r="/MoMAWork-/ai-task-flow.svg",g=JSON.parse('{"title":"第 1 章 初识 momawork-rs","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md"};function e(l,t,i,p,h,c){return o(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-1-章-初识-momawork-rs" tabindex="-1">第 1 章 初识 momawork-rs <a class="header-anchor" href="#第-1-章-初识-momawork-rs" aria-label="Permalink to &quot;第 1 章 初识 momawork-rs&quot;">​</a></h1><blockquote><p>本章目标：5 分钟内建立对 momawork-rs 的完整认知——我是谁、能做什么、不能做什么，以及一次成功的 AI 任务长什么样。学完本章，你就能判断&quot;这件事该不该交给 AI 做&quot;。</p></blockquote><h2 id="_1-1-我是谁-一个坐在你电脑里的同事" tabindex="-1">1.1 我是谁：一个坐在你电脑里的同事 <a class="header-anchor" href="#_1-1-我是谁-一个坐在你电脑里的同事" aria-label="Permalink to &quot;1.1 我是谁：一个坐在你电脑里的同事&quot;">​</a></h2><p>我是 <strong>momawork-rs</strong>，一个运行在 MomaWork 桌面程序里的 AI 工作助手。比起&quot;聊天机器人&quot;这个称呼，更准确的比喻是：<strong>一个坐在你电脑旁边、能真正动手干活的同事</strong>。</p><p>普通聊天机器人只会在对话框里输出文字；而我不一样——我拥有和你相同的工作目录，看得见你的文件，改得了你的代码，跑得了你的命令。</p><h3 id="_1-1-1-我与普通-ai-聊天工具的三个本质区别" tabindex="-1">1.1.1 我与普通 AI 聊天工具的三个本质区别 <a class="header-anchor" href="#_1-1-1-我与普通-ai-聊天工具的三个本质区别" aria-label="Permalink to &quot;1.1.1 我与普通 AI 聊天工具的三个本质区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区别</th><th>普通聊天工具</th><th>momawork-rs</th></tr></thead><tbody><tr><td><strong>工作环境</strong></td><td>云端一个隔离的对话框</td><td>你的真实工作目录，与项目共享文件</td></tr><tr><td><strong>动手能力</strong></td><td>只能生成文字/图片</td><td>读写文件、执行命令、运行脚本、调用 Skill</td></tr><tr><td><strong>记忆方式</strong></td><td>每次对话从零开始</td><td>持久记忆文件，跨会话记得你的偏好与项目背景</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一句话记住我</p><p><strong>聊天机器人给你&quot;建议&quot;，我给你&quot;结果&quot;。</strong> 你说&quot;帮我整理这个目录&quot;，我会真的动手整理，而不是告诉你&quot;你应该整理&quot;。</p></div><h3 id="_1-1-2-关于我的名字" tabindex="-1">1.1.2 关于我的名字 <a class="header-anchor" href="#_1-1-2-关于我的名字" aria-label="Permalink to &quot;1.1.2 关于我的名字&quot;">​</a></h3><p><code>momawork-rs</code> 中的 <code>rs</code> 代表我的技术底座（Rust 驱动的高性能运行内核）。你不用记住这个名字的含义——在 MomaWork 里，你只需要知道：<strong>我是你随时可以召唤的 AI 同事</strong>。</p><h2 id="_1-2-我能做什么-八大核心能力" tabindex="-1">1.2 我能做什么：八大核心能力 <a class="header-anchor" href="#_1-2-我能做什么-八大核心能力" aria-label="Permalink to &quot;1.2 我能做什么：八大核心能力&quot;">​</a></h2><p>以下是我的&quot;岗位说明书&quot;——每一项能力都能单独使用，也能组合成复杂的任务流：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>典型示例</th><th>对应章节</th></tr></thead><tbody><tr><td>📄 读写文件</td><td>创建、编辑、查看项目里的任何文本文件</td><td>写报告、改配置、读日志</td><td>第 3 章</td></tr><tr><td>⌨️ 执行命令</td><td>在 shell 里运行命令、脚本、程序</td><td>装依赖、跑测试、批量改名</td><td>第 3 章</td></tr><tr><td>🔍 搜索定位</td><td>按文件名或内容快速找到目标</td><td>找函数、搜报错、查文档</td><td>第 11 章</td></tr><tr><td>🧩 调用 Skill</td><td>加载预设的专业工作方法</td><td>提交代码、评审 PR、处理 PDF</td><td>第 5、17 章</td></tr><tr><td>🧠 记忆系统</td><td>持久保存用户与项目上下文</td><td>记住你的偏好、项目背景、约定</td><td>第 6、20 章</td></tr><tr><td>📋 计划模式</td><td>先规划再执行的长任务</td><td>大重构、多步骤交付</td><td>第 7 章</td></tr><tr><td>👥 AI 团队</td><td>多智能体并行协作</td><td>开发 + 测试 + 文档并行推进</td><td>第 8、16 章</td></tr><tr><td>⚡ 子代理</td><td>后台并行处理子任务</td><td>并行调研、分块生成</td><td>第 8 章</td></tr></tbody></table><h3 id="_1-2-1-这些能力如何组合" tabindex="-1">1.2.1 这些能力如何组合 <a class="header-anchor" href="#_1-2-1-这些能力如何组合" aria-label="Permalink to &quot;1.2.1 这些能力如何组合&quot;">​</a></h3><p>单一能力解决小问题，<strong>组合能力解决真问题</strong>。例如一个&quot;周报自动化&quot;任务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我生成这周的周报</span></span>
<span class="line"><span>我：</span></span>
<span class="line"><span>  ① 搜索定位 → 找出本周修改过的所有文件（第 11 章）</span></span>
<span class="line"><span>  ② 读写文件 → 读取每个文件的改动内容</span></span>
<span class="line"><span>  ③ 执行命令 → 统计代码量、运行测试确认状态</span></span>
<span class="line"><span>  ④ 调用 Skill → 用「周报模板 Skill」按格式输出</span></span>
<span class="line"><span>  ⑤ 交付 → 生成 docs/周报-第33周.md，等你检查</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">组合原则</p><p><strong>先想清楚&quot;这件事需要哪些能力&quot;，再开口。</strong> 你不需要懂技术细节，但描述越接近任务本身，我组合能力就越准。</p></div><h2 id="_1-3-一次-ai-任务里到底发生了什么" tabindex="-1">1.3 一次 AI 任务里到底发生了什么 <a class="header-anchor" href="#_1-3-一次-ai-任务里到底发生了什么" aria-label="Permalink to &quot;1.3 一次 AI 任务里到底发生了什么&quot;">​</a></h2><p>为了不把 AI 当&quot;魔法&quot;，我们拆开看一次任务的全过程。以下图为例，一次成功的 AI 任务是一个<strong>五步协作循环</strong>：</p><p><img src="`+r+`" alt="一次 AI 任务的全过程"></p><h3 id="_1-3-1-五步详解" tabindex="-1">1.3.1 五步详解 <a class="header-anchor" href="#_1-3-1-五步详解" aria-label="Permalink to &quot;1.3.1 五步详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>谁</th><th>做什么</th><th>你的角色</th></tr></thead><tbody><tr><td>① 描述任务</td><td>你</td><td>说清目标、输入、验收标准</td><td><strong>主演</strong></td></tr><tr><td>② 理解与规划</td><td>助手</td><td>读文件、问口径、拆步骤</td><td>协作</td></tr><tr><td>③ 动手执行</td><td>助手</td><td>读写文件、跑命令、调 Skill</td><td>监督</td></tr><tr><td>④ 检查修订</td><td>你</td><td>看中间产物、提反馈</td><td><strong>关键</strong></td></tr><tr><td>⑤ 交付沉淀</td><td>助手</td><td>交付物 + 把方法存成 Skill/记忆</td><td>验收</td></tr></tbody></table><h3 id="_1-3-2-为什么第-4-步最关键" tabindex="-1">1.3.2 为什么第 ④ 步最关键 <a class="header-anchor" href="#_1-3-2-为什么第-4-步最关键" aria-label="Permalink to &quot;1.3.2 为什么第 ④ 步最关键&quot;">​</a></h3><p>统计上，AI 任务翻车最多的环节，不是&quot;AI 能力不够&quot;，而是<strong>第 ① 步需求没说清 + 第 ④ 步没有中间检查</strong>。</p><ul><li>❌ 错误示范：<code>帮我做个 PPT</code>（没有目标、没有素材、没有风格要求）</li><li>✅ 正确示范：<code>帮我把 docs/项目总结.md 转成一份 10 页的汇报 PPT，风格简洁商务，标题用「Q3 项目复盘」，最后附一页风险清单</code></li></ul><div class="warning custom-block"><p class="custom-block-title">重要原则</p><p><strong>永远要求&quot;可检查的中间产物&quot;，而不是&quot;直接给最终结论&quot;。</strong> 例如改代码前先给我看改动计划；写报告先给我大纲。这样即使出错，损失也可控、可回退。</p></div><h2 id="_1-4-我的边界-诚实版-我不能做什么" tabindex="-1">1.4 我的边界：诚实版&quot;我不能做什么&quot; <a class="header-anchor" href="#_1-4-我的边界-诚实版-我不能做什么" aria-label="Permalink to &quot;1.4 我的边界：诚实版&quot;我不能做什么&quot;&quot;">​</a></h2><p>了解边界和了解能力同样重要。<strong>以下 5 条请你务必记住</strong>：</p><h3 id="_1-4-1-五个边界" tabindex="-1">1.4.1 五个边界 <a class="header-anchor" href="#_1-4-1-五个边界" aria-label="Permalink to &quot;1.4.1 五个边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>边界</th><th>具体含义</th><th>应对方式</th></tr></thead><tbody><tr><td>1</td><td><strong>我活在工作目录里</strong></td><td>看不到你整个硬盘，只能访问当前项目及相关路径</td><td>把需要的文件放进工作目录再让我处理</td></tr><tr><td>2</td><td><strong>网络访问有限</strong></td><td>不能随意浏览互联网，除非你提供工具/链接</td><td>给我下载链接，或把内容贴给我</td></tr><tr><td>3</td><td><strong>危险操作先确认</strong></td><td>删除、覆盖、推送远程仓库等不可逆动作，我会先问你</td><td>收到确认询问时，看清再回答</td></tr><tr><td>4</td><td><strong>记忆是文件</strong></td><td>我的记忆存在项目 memory 目录，可查看/修改/删除</td><td>敏感信息不要写进任务描述</td></tr><tr><td>5</td><td><strong>我可能出错</strong></td><td>尤其是数据口径、需求理解上的偏差</td><td>用&quot;中间产物检查法&quot;控制风险</td></tr></tbody></table><h3 id="_1-4-2-什么任务不适合交给我" tabindex="-1">1.4.2 什么任务不适合交给我 <a class="header-anchor" href="#_1-4-2-什么任务不适合交给我" aria-label="Permalink to &quot;1.4.2 什么任务不适合交给我&quot;">​</a></h3><ul><li>❌ 需要<strong>实时联网浏览</strong>的任务（除非接好工具）</li><li>❌ 需要<strong>你签字确认</strong>的对外承诺（我只做草稿）</li><li>❌ 涉及<strong>敏感机密</strong>的内容（本地环境相对安全，但别把密码写进项目文件）</li><li>❌ 需要<strong>主观判断品味</strong>的最终拍板（我可以给建议，决定权在你）</li></ul><div class="tip custom-block"><p class="custom-block-title">判断口诀</p><p><strong>&quot;能检查、可回退、无风险&quot;的任务 → 大胆交给我；反之 → 先做半步试探。</strong></p></div><h2 id="_1-5-一次成功的合作长什么样" tabindex="-1">1.5 一次成功的合作长什么样 <a class="header-anchor" href="#_1-5-一次成功的合作长什么样" aria-label="Permalink to &quot;1.5 一次成功的合作长什么样&quot;">​</a></h2><p>把前面所有内容浓缩成一个真实场景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：写一份《Q3 运营复盘》，数据在 data/ 目录下，用模板 docs/template.md，</span></span>
<span class="line"><span>    重点分析用户增长与留存，最后给出 3 条可执行建议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我（先规划）：好的，我先读模板和数据 → 确认统计口径（哪个时间范围？留存怎么定义？）</span></span>
<span class="line"><span>我（再执行）：读取 data/ 全部 4 个文件 → 按模板生成初稿 → 标注 2 处数据口径疑问</span></span>
<span class="line"><span>你：口径按自然月，留存按次月活跃；第 2 条建议再具体一点</span></span>
<span class="line"><span>我（修订）：更新口径与建议 → 生成最终版 docs/周报/Q3运营复盘.md → 附数据明细表</span></span></code></pre></div><p><strong>关键不是&quot;我说了什么漂亮话&quot;，而是每一步都可检查、可回退、有产物。</strong></p><h2 id="_1-6-你的第一个-60-秒上手" tabindex="-1">1.6 你的第一个 60 秒上手 <a class="header-anchor" href="#_1-6-你的第一个-60-秒上手" aria-label="Permalink to &quot;1.6 你的第一个 60 秒上手&quot;">​</a></h2><p>不用读完整个白皮书，现在就试：</p><ol><li>打开 MomaWork，新建或打开一个项目文件夹；</li><li>对我说：<code>你好，介绍一下你自己，以及你现在的工作目录</code>；</li><li>再对我说：<code>列出当前工作目录里的所有文件，按类型分组展示</code>；</li><li>看看我的回答——这就是你与 AI 同事的第一次协作。</li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果第 2、3 步我的回答和你预期不符（比如工作目录不对），立刻告诉我。<strong>第一次对话就校准&quot;工作目录&quot;认知，能避免后面 80% 的错乱。</strong></p></div><h2 id="_1-7-本章练习" tabindex="-1">1.7 本章练习 <a class="header-anchor" href="#_1-7-本章练习" aria-label="Permalink to &quot;1.7 本章练习&quot;">​</a></h2><ol><li><strong>判断题</strong>：momawork-rs 能直接浏览互联网获取最新新闻吗？（答案：不能，需要你提供链接或工具）</li><li><strong>组合题</strong>：任务&quot;把项目里所有 TODO 注释找出来并汇总成清单&quot;，需要哪些能力组合？</li><li><strong>实践题</strong>：告诉我你最近想解决的一个真实问题，我们一起把它变成第一个任务。</li><li><strong>边界题</strong>：以下哪个任务不适合交给我：A. 批量重命名文件 B. 帮你在微博上自动发言 C. 统计报表数据（答案：B）</li></ol><hr><blockquote><p><strong>小结</strong>：我是一台&quot;任务执行器&quot;，不是&quot;聊天机器&quot;。我的能力清单 = 8 项核心能力 × 自由组合；我的工作方式 = 五步协作循环；我的边界 = 5 条诚实清单。<strong>你的表达越接近任务（有目标、有输入、有验收标准），我的输出就越接近交付物。</strong> 下一章，我们学习如何把需求讲清楚。</p></blockquote>`,45)])])}const b=a(n,[["render",e]]);export{g as __pageData,b as default};
